/* Intuition checks for "Exam 2 on one page": about ten "what happens, and why" questions spliced in after each theory
   section (loaded after e2-one.js), plus one shuffled drill of all of them. Every option explains itself. */
(function () {
  'use strict';
  const { R, Q, G } = C;
  // q(question, [right, wrong, wrong, wrong], [why for each wrong], solution); options are shuffled on the page
  const q = (text, opts, whys, sol) => Q(text, opts, 0, [null, ...whys], sol, { tags: ['gym'] });

  const S = {};
  // ============================================================ 1. the cast: bands, carriers, Fermi level
  S['1'] = [
    q(md`On an equilibrium band diagram, $E_c$ slopes **down** to the right while $E_F$ is flat. Where are the electrons densest?`,
      ['on the right, where $E_c$ is closest to $E_F$', 'on the left, where $E_c$ is highest and there are more states', 'evenly spread, since $E_F$ is flat', 'wherever the slope is steepest'],
      ['Higher $E_c$ above $E_F$ means fewer electrons.', 'Flat $E_F$ means no net current, not uniform density.', 'Density depends on the gap $E_c - E_F$, not on the slope.'],
      md`Electron density depends on how far $E_c$ sits above $E_F$: every 60 meV closer is 10× more electrons.`),
    q(md`An n-type Si sample ($10^{16}\ \text{cm}^{-3}$) is heated from 300 K to 400 K. What happens to the carrier densities?`,
      ['electrons barely change; holes rise enormously', 'both rise by the same factor', 'electrons rise sharply as more donors ionize; holes stay the same', 'electrons fall; holes rise'],
      ['$np = n_i^2$ grows, but $n$ is pinned at $N_d$.', 'The donors were already fully ionized.', 'Electrons stay at $N_d$.'],
      md`$n \approx N_d$ is set by the doping and doesn't move. The minority holes are $n_i^2/N_d$, and $n_i^2$ grows exponentially with temperature: many orders of magnitude here. This is why leakage soars when a diode heats up.`),
    q(md`Why do holes "float up" on a band diagram?`,
      ['it plots electron energy; holes gain energy going down', 'holes are lighter than electrons, so they rise like bubbles in water', 'holes feel no force from the field', 'the valence band sits on top'],
      ['Mass has nothing to do with direction.', 'Holes feel the field (opposite force to electrons).', 'It is below the conduction band.'],
      md`A hole is a missing electron. Pushing it deeper into the valence band means pulling a deeper electron up, which costs energy, so on an electron-energy diagram holes rise like bubbles.`),
    q(md`$E_F$ sits 0.3 eV above $E_i$ in Si at 300 K ($n_i = 1.5\times10^{10}$). Roughly what is $n$?`,
      ['$1.5\\times10^{15}\\ \\text{cm}^{-3}$', '$1.5\\times10^{13}\\ \\text{cm}^{-3}$', '$4.5\\times10^{9}\\ \\text{cm}^{-3}$', '$1.5\\times10^{17}\\ \\text{cm}^{-3}$'],
      ['That is 3 decades; 0.3 eV is 5.', 'That is below $n_i$: $E_F$ above $E_i$ means more electrons.', 'That is 7 decades.'],
      md`60 mV per decade: 0.3 eV is 5 decades, so $n \approx n_i\times10^5 = 1.5\times10^{15}$.`),
    q(md`Why does the hole density in n-type silicon matter so much for a diode, when holes are so scarce?`,
      ['the diode current is set by injected minority carriers', 'holes carry most of the current in n-type material at low fields', 'holes set the Fermi level in n-type material', 'holes determine the mobility of electrons'],
      ['Far from the junction electrons carry the current.', '$E_F$ is set by the majority electrons.', 'Mobility depends on impurities, not on holes.'],
      md`Bias multiplies the **minority** density at the junction edge by $e^{qV/kT}$; that injected excess, diffusing and recombining, *is* the diode current.`),
    q(md`Si ($n_i = 1.5\times10^{10}$) is doped with $N_d = 10^{15}\ \text{cm}^{-3}$. The hole density is about…`,
      ['$2\\times10^{5}\\ \\text{cm}^{-3}$', '$1.5\\times10^{10}\\ \\text{cm}^{-3}$', '$10^{15}\\ \\text{cm}^{-3}$', '$10^{-15}\\ \\text{cm}^{-3}$'],
      ['Doping pushes holes far below $n_i$.', 'That is the electron density.', 'Use $n_i^2/N_d$, not $1/N_d$.'],
      md`$p = n_i^2/N_d = 2.25\times10^{20}/10^{15} \approx 2\times10^5$. More electrons, fewer holes: the product is fixed.`),
    q(md`Why does adding donors **lower** the number of holes?`,
      ['more electrons find holes faster, so fewer survive', 'donors bond to holes and trap them', 'donors raise the band gap', 'holes are pushed out through the contacts by the donor ions'],
      ['Donors are positive ions; they repel holes, they do not bond.', 'Doping does not change the gap (until very heavy).', 'Nothing leaves; it is a balance.'],
      md`Generation is fixed by temperature; recombination is $\propto np$. More electrons means each hole is caught sooner, so the steady hole count drops until $np = n_i^2$ again.`),
    q(md`Where is $E_F$ in p-type Si with $N_a = 10^{17}\ \text{cm}^{-3}$?`,
      ['a little above $E_v$', 'a little below $E_c$', 'exactly at midgap', 'inside the valence band'],
      ['That is n-type.', 'That is intrinsic.', 'Only for degenerate doping (well above $10^{19}$).'],
      md`Many holes means $E_F$ close to $E_v$: about $0.42$ eV below $E_i$ ($7$ decades × 60 mV).`),
    q(md`A material has a wider band gap. At the same temperature its $n_i$ is…`,
      ['far smaller', 'slightly larger', 'the same', 'far larger'],
      ['A wider gap is harder to jump.', '$n_i$ depends on the gap exponentially.', 'It goes the other way.'],
      md`$n_i \propto e^{-E_g/2kT}$: GaAs ($1.42$ eV) has $n_i \sim 10^6$ vs Si's $10^{10}$.`),
    q(md`Donor levels sit about 45 meV below $E_c$. Why are almost all of them ionized at 300 K?`,
      ['it is under 2 kT, with many empty states above', 'the donor ions repel their electrons', 'room light ionizes them', 'the built-in field of the donor ions pulls the electrons off'],
      ['The ion attracts its electron.', 'It happens in the dark.', 'A uniform sample has no field.'],
      md`Thermal energy easily lifts the loosely bound electron into the huge number of empty conduction states, so $n \approx N_d$.`),
  ];

  // ============================================================ 2. drift and diffusion
  S['2'] = [
    q(md`On an equilibrium band diagram with $E_c$ sloping down to the right, which way does the **electron diffusion current** point?`,
      ['to the right', 'to the left', 'there is none in equilibrium', 'along the field'],
      ['That is the direction the electrons themselves move.', 'Each component is there; they just cancel.', 'Diffusion ignores the field.'],
      md`Electrons are densest on the right, so they diffuse left; negative charge moving left is current to the right. Their drift current points left (along the field, which points uphill to the high bands on the left), and the two cancel.`),
    q(md`Two Si samples at 300 K have mobilities 1000 and 500 $\text{cm}^2/\text{V·s}$. Their diffusion coefficients…`,
      ['are in the same 2:1 ratio', 'are equal, since the temperature is equal', 'are in a 1:2 ratio', 'depend only on doping, not on mobility'],
      ['Einstein ties $D$ to $\\mu$: $D = \\mu kT/q$.', 'Higher mobility means faster diffusion, not slower.', 'Doping affects $D$ only through $\\mu$.'],
      md`Same scattering slows both drift and diffusion: $D/\mu = kT/q$, so $D$ follows $\mu$.`),
    q(md`A uniformly doped n-type bar has a uniform field along it. Is there a diffusion current?`,
      ['no: with no gradient there is only drift', 'yes: the field piles carriers up at one end, creating a gradient', 'yes, equal and opposite to the drift', 'only for the minority holes'],
      ['A uniform bar with ohmic contacts stays uniform.', 'Then no current would flow, but this bar carries current.', 'Uniform holes too: no gradient.'],
      md`Diffusion needs a concentration gradient. A uniform bar carries pure drift current.`),
    q(md`Electrons diffuse to the right, and so do holes, at the same particle rate. The net diffusion current is…`,
      ['zero: their currents cancel', 'twice the electron current', 'equal to the hole current alone', 'to the left, from the electrons'],
      ['Opposite charges moving the same way carry opposite currents.', 'The electron current is not zero.', 'The hole current points right and cancels it.'],
      md`Electrons moving right carry current left; holes moving right carry current right. Equal rates: they cancel. That is why an electron–hole cloud (as in Haynes–Shockley) can diffuse with no net current.`),
    q(md`A field points to the right along an n-type bar. The electron drift **current** points…`,
      ['to the right', 'to the left', 'nowhere: electrons ignore fields', 'up the band diagram'],
      ['That is where the electrons go, not the current.', 'They feel a force $-q\\mathscr{E}$.', 'Band diagrams are not directions in space.'],
      md`Electrons drift left (against the field), and negative charge moving left is current to the right. Drift current always points along the field, for both carriers.`),
    q(md`At low field, doubling the field in a bar doubles…`,
      ['the drift velocity and the current', 'the mobility, since carriers speed up between collisions', 'the carrier density', 'the diffusion current'],
      ['Mobility is a material property (until velocity saturation).', 'Carriers come from doping, not from the field.', 'A uniform bar has no diffusion.'],
      md`$v_d = \mu\mathscr{E}$ and $J = qn\mu\mathscr{E}$: Ohm's law.`),
    q(md`Why does mobility fall as lightly doped Si heats up?`,
      ['lattice vibrations scatter carriers more often', 'carriers get heavier when hot, so they accelerate more slowly', 'the band gap shrinks', 'more donors ionize'],
      ['The effective mass barely changes.', 'The gap does not set mobility.', 'They were already ionized.'],
      md`Phonon scattering grows with temperature. (Impurity scattering, which dominates in heavily doped or cold samples, actually weakens as carriers move faster.)`),
    q(md`On a band diagram, which way does the electric field point?`,
      ['toward where the bands are higher', 'downhill, toward where the bands are lower', 'along $E_F$', 'always from left to right'],
      ['That is the way electrons roll.', '$E_F$ is not a field.', 'It depends on the tilt.'],
      md`Bands are electron energy $= -qV$: high bands mean low potential, and fields point from high to low potential. Electrons roll down, holes float up, the field points uphill.`),
    q(md`A minority density is tiny, but it can still carry a large diffusion current if…`,
      ['it changes steeply over a short distance', 'the field across it is large enough to sweep it along', 'its mobility is low', 'the sample is very long'],
      ['Field drives drift, which needs many carriers.', 'Low mobility means low $D$.', 'Long regions make gentle slopes.'],
      md`Diffusion current is $qD\,dp/dx$: it cares about the slope, not the size. This is exactly how a few injected holes carry a diode's current.`),
    q(md`The resistivity of n-type Si with $N_d = 10^{16}\ \text{cm}^{-3}$ is set by…`,
      ['the electrons: $\\rho \\approx 1/(q\\mu_n N_d)$', 'the holes: they are slower, so they limit the current', 'both carriers equally', 'the intrinsic density $n_i$'],
      ['There are about $10^4$ holes per cm³.', 'They differ by 12 orders of magnitude.', 'Doping swamps $n_i$.'],
      md`Conductivity is $q(n\mu_n + p\mu_p)$, and $n$ wins by many decades.`),
  ];

  // ============================================================ 3. equilibrium and leaving it
  S['3'] = [
    q(md`A Si sample in equilibrium has more donors on the left than on the right. Which is true?`,
      ['$E_F$ is flat; the bands tilt; drift cancels diffusion', '$E_F$ tilts to follow the doping, and a small current flows', 'the bands stay flat because the sample is neutral', 'electrons diffuse right and nothing stops them'],
      ['In equilibrium $E_F$ is always flat and the net current is zero.', 'A doping gradient tilts the bands; neutrality is only approximate there.', 'The built-in field from the uncovered donors pushes back.'],
      md`Electrons diffuse toward the low-doping side, uncovering donors; that charge makes a field whose drift exactly cancels the diffusion. $E_F$ stays flat; the bands bend instead.`),
    q(md`In which situation is the Fermi level **not** a single flat line?`,
      ['a diode under forward bias', 'an unbiased p-n junction in the dark', 'a sample with a doping gradient, in the dark', 'a uniformly doped bar with no contacts'],
      ['Equilibrium: flat $E_F$, bands bend.', 'Equilibrium again: flat.', 'Equilibrium: flat.'],
      md`Any bias or light takes the device out of equilibrium: $E_F$ splits into $F_n$ and $F_p$, and they tilt wherever current flows.`),
    q(md`Uniform light adds $10^{13}$ pairs per cm³ to n-type Si with $n_0 = 10^{16}$. Which quasi-Fermi level moves noticeably?`,
      ['$F_p$ only: holes went from tiny to $10^{13}$', '$F_n$ only: electrons are the majority, so they set the level', 'both move by the same amount', 'neither: light does not move them'],
      ['$10^{13}$ extra electrons is 0.1% of $10^{16}$.', 'The relative changes are wildly different.', 'Light creates excess carriers, which is what splits them.'],
      md`Same number of pairs, but a 0.1% change for electrons and a gigantic one for holes ($p_0 \approx 2\times10^4$). Low-level injection: the majority level stays put, the minority level moves.`),
    q(md`In a region, $F_p$ is perfectly flat. The hole current there is…`,
      ['zero', 'pure drift', 'pure diffusion', 'at its maximum'],
      ['A flat quasi-Fermi level means drift and diffusion cancel.', 'Same reason.', 'Current is set by the slope.'],
      md`$J_p \propto p\,dF_p/dx$: no slope, no net hole current.`),
    q(md`A sample is lit uniformly, with no contacts. $F_n$ and $F_p$ are…`,
      ['split apart but both flat', 'equal and flat', 'split apart and tilted toward the surface', 'equal but tilted'],
      ['Light separates them.', 'No gradients, so no tilt.', 'Equal would mean equilibrium.'],
      md`Excess carriers split them by the same amount everywhere; with nothing flowing, both are flat.`),
    q(md`What does a **tilt** in a quasi-Fermi level tell you?`,
      ['that carrier has a net current there', 'the doping changes there, so the level follows it', 'the temperature changes there', 'the bands are bent there'],
      ['Doping gradients bend bands, not $E_F$.', 'Not what the slope measures.', 'Bent bands with flat $E_F$ is equilibrium.'],
      md`The slope of $F_n$ (or $F_p$) is the total driving force, drift and diffusion together. A tilt means net current; steeper where there are fewer carriers to carry it.`),
    q(md`Why must $E_F$ be flat in equilibrium?`,
      ['any tilt would drive a net current, and none flows', 'the electric field is zero everywhere inside the sample in equilibrium', 'the doping is uniform', 'the bands are flat'],
      ['Junctions have big fields in equilibrium.', 'Junctions are not uniform.', 'Bands bend in equilibrium.'],
      md`Equilibrium means no net flow of anything. Electrons would flow toward lower $E_F$, so $E_F$ has to be level.`),
    q(md`Under steady light, $np$ compared with $n_i^2$ is…`,
      ['larger', 'equal', 'smaller', 'zero'],
      ['Only in equilibrium.', 'That is extraction (reverse bias).', 'No.'],
      md`$np = n_i^2 e^{(F_n - F_p)/kT}$: light splits the levels apart, so $np > n_i^2$ and recombination beats generation.`),
    q(md`Low-level injection means…`,
      ['the excess is small next to the majority density', 'the excess is small next to the minority density', 'the light is dim to the eye', 'the current is small'],
      ['The excess usually dwarfs the minority density.', 'It is about densities, not brightness.', 'It is about densities, not current.'],
      md`$\delta n = \delta p \ll n_0$ (in n-type): the majority density barely changes, so the recombination rate is linear in the excess.`),
    q(md`$F_n - F_p$ measures…`,
      ['how far $np$ is from $n_i^2$', 'the band gap', 'the doping', 'the electric field across the sample'],
      ['The gap is fixed.', 'Doping sets where $E_F$ was.', 'The slope relates to current, not the split.'],
      md`$np = n_i^2 e^{(F_n - F_p)/kT}$. Zero split is equilibrium; a split of $qV$ is a diode at voltage $V$.`),
  ];

  // ============================================================ 4. excess carriers: lifetime, L, Haynes–Shockley
  S['4'] = [
    q(md`The light on a sample is doubled (same doping). The steady-state excess…`,
      ['doubles', 'quadruples', 'rises by √2', 'stays the same'],
      ['The excess is linear in generation.', 'Diffusion length has the √; excess does not.', 'Lifetime is fixed; generation doubled.'],
      md`$\delta = g\tau$: twice the faucet, same drain, twice the level (in low-level injection).`),
    q(md`$D$ is made 4× larger at the same lifetime. The diffusion length…`,
      ['doubles', 'quadruples', 'halves', 'stays the same'],
      ['Random walks grow as a square root.', 'More diffusion means farther, not shorter.', 'It depends on $D$.'],
      md`$L = \sqrt{D\tau}$.`),
    q(md`In Haynes–Shockley, the drift field is doubled. Compared with before, the pulse arrives…`,
      ['in half the time, narrower and taller', 'in half the time, but wider and shorter', 'at the same time, but taller', 'in a quarter of the time'],
      ['Less time means less spreading and less recombination.', 'Arrival depends on the drift speed.', 'Speed is linear in field.'],
      md`Twice the drift speed halves the transit time. In less time the pulse spreads less ($\propto\sqrt{t}$) and loses fewer carriers to recombination.`),
    q(md`In Haynes–Shockley, what tells you the **diffusion coefficient**?`,
      ['how fast the pulse widens', 'how fast the pulse moves', 'how fast its area shrinks', 'its height at the detector'],
      ['That gives mobility.', 'That gives lifetime.', 'Height mixes all three effects.'],
      md`Speed → $\mu$, widening (∝ $\sqrt{Dt}$) → $D$, shrinking area → $\tau$.`),
    q(md`A long bar is lit at one end. At one diffusion length in, the diffusion current is what fraction of its surface value?`,
      ['37%', '50%', '0%', '100%'],
      ['The decay is exponential, not linear.', 'It has not all recombined yet.', 'Carriers recombine as they go.'],
      md`Both the excess and its slope fall as $e^{-x/L}$: $e^{-1} \approx 0.37$.`),
    q(md`An n region is shortened from much longer than $L_p$ to $\ell = L_p/10$, with the same edge excess. The hole current…`,
      ['rises about 10×', 'falls about 10×', 'stays the same', 'rises about √10×'],
      ['A shorter region makes the line steeper.', 'The slope sets the current.', 'Slope ∝ 1/ℓ, not 1/√ℓ.'],
      md`The profile becomes a straight line to zero at the contact: slope $\Delta/\ell$ instead of $\Delta/L$. Ten times steeper, ten times the current.`),
    q(md`Why is the excess-carrier profile in a very short region a **straight line**?`,
      ['carriers reach the contact before recombining', 'the electric field is uniform there', 'recombination is fastest in short regions, near contacts', 'the doping is graded'],
      ['There is no field; it is diffusion.', 'Lifetime does not depend on length.', 'Nothing about grading here.'],
      md`With no recombination along the way, the diffusion current is the same everywhere, so the slope is constant: a straight line from the edge value to zero at the contact.`),
    q(md`Where does the energy of recombining carriers mostly go in silicon?`,
      ['heat in the lattice', 'light at the band-gap energy', 'back into the field', 'into new electron–hole pairs'],
      ['That is GaAs; Si is indirect.', 'Fields do not absorb it.', 'That would need more energy than the gap.'],
      md`Indirect-gap Si recombines mostly through traps and phonons, so the energy becomes heat. That is why Si makes poor LEDs.`),
    q(md`Light is switched off. The excess falls to about 37% of its starting value after…`,
      ['one lifetime τ', 'one diffusion length', 'half a lifetime', 'τ ln 2'],
      ['That is a distance, not a time.', 'That leaves about 61%.', 'That is the half-life: 50%.'],
      md`$\delta(t) = \delta(0)e^{-t/\tau}$.`),
    q(md`A bar is lit at one end in steady state. Why doesn't the excess keep piling up?`,
      ['recombination removes them as fast as they arrive', 'the field from the excess pushes new carriers back out', 'the light saturates', 'the far contact absorbs them all'],
      ['There is no field in a uniform bar.', 'Generation stays constant.', 'In a long bar they never reach it.'],
      md`Steady state means every point balances: diffusion in = diffusion out + recombination. That balance is what makes the decay exponential with length $L$.`),
  ];

  // ============================================================ 4b. majority density sets the minority lifetime
  S['4b'] = [
    q(md`The majority density is doubled (same light). The minority lifetime…`,
      ['halves: partners are twice as common', 'doubles: more carriers protect each other', 'is unchanged: lifetime is a material constant', 'halves, but the steady excess is unchanged'],
      ['More partners means faster recombination.', 'For direct recombination, $\\tau \\propto 1/n_0$.', 'Shorter lifetime with the same generation lowers the excess.'],
      md`A minority hole dies when it meets an electron. Twice the electrons, twice the rate, half the lifetime, and the steady excess $g\tau$ halves too.`),
    q(md`Light is switched off. Which sample's excess carriers vanish fastest?`,
      ['the most heavily doped one', 'the most lightly doped one', 'the one with the highest mobility', 'all at the same rate'],
      ['Fewer majority partners means slower recombination.', 'Mobility affects motion, not recombination here.', 'Lifetime depends on the majority density.'],
      md`More majority carriers, more partners for each minority carrier, shorter lifetime.`),
    q(md`A sample has $N_D = N_A = 10^{17}\ \text{cm}^{-3}$. Compared with undoped Si, it has…`,
      ['about the same carriers, much lower mobility', 'far more carriers, since every ion adds one, and lower mobility', 'the same carriers and the same mobility', 'fewer carriers and higher mobility'],
      ['The donors and acceptors cancel; no net carriers are added.', '$2\\times10^{17}$ ions scatter carriers.', 'Compensation never raises mobility.'],
      md`Carriers follow the **net** doping (zero, so about $n_i$); mobility follows the **total** ions ($2\times10^{17}$).`),
    q(md`In lit n-type Si, pairs are made together and recombine together. Why do we track only the **holes'** lifetime?`,
      ['holes change hugely; electrons barely notice', 'electrons never recombine', 'holes move faster than electrons', 'electrons have no lifetime in n-type material at all'],
      ['Every recombination removes one of each.', 'Holes are slower, and speed is irrelevant here anyway.', 'They do; it just does not matter.'],
      md`Both lose one per recombination, but $10^{13}$ added to $10^{16}$ electrons is invisible, while holes go from $10^4$ to $10^{13}$. The minority excess is the thing that changes, so its decay is the story.`),
    q(md`Bathtub picture: light is the faucet, recombination the drain. Heavier majority doping is…`,
      ['a wider drain: same faucet, lower level', 'a bigger faucet: more carriers, so a higher level', 'a deeper tub: same level', 'a narrower drain: higher level'],
      ['Doping does not change the light.', 'The level depends on faucet and drain.', 'That is lighter doping.'],
      md`Steady level $= g\tau$. More partners drain the minority carriers faster, so the same light holds a lower excess.`),
    q(md`Recombination is $\alpha_r np$. In n-type Si with $\delta p \ll n_0$, the excess recombination rate is about…`,
      ['$\\alpha_r n_0\\,\\delta p$: linear in the excess', '$\\alpha_r\\,\\delta p^2$: quadratic, since both carriers are excess', '$\\alpha_r n_i^2$', '$\\alpha_r n_0^2$'],
      ['That is high-level injection.', 'That is thermal recombination, canceled by generation.', 'That ignores the holes.'],
      md`$n \approx n_0$ stays fixed, so the extra rate is $\alpha_r n_0\delta p = \delta p/\tau$ with $\tau = 1/(\alpha_r n_0)$. There is the majority density sitting inside the minority lifetime.`),
    q(md`Under **high-level** injection ($\delta p \gg n_0$), the lifetime…`,
      ['shortens as the light gets brighter', 'is fixed at $1/(\\alpha_r n_0)$ whatever the light', 'grows as the light gets brighter', 'becomes infinite'],
      ['Now the excess itself supplies the partners.', 'More carriers find each other faster.', 'No.'],
      md`The rate becomes $\alpha_r\delta p^2$, so the effective lifetime is $1/(\alpha_r\delta p)$: the more excess, the faster it dies.`),
    q(md`Two samples, $n_0 = 10^{15}$ and $10^{17}\ \text{cm}^{-3}$, same light. The steady minority excess in the lighter one is…`,
      ['100× larger', '100× smaller', '10× larger', 'the same'],
      ['Lighter doping means fewer partners.', 'It is linear in τ, not √τ.', 'τ differs, so the excess differs.'],
      md`$\tau \propto 1/n_0$ and $\delta = g\tau$: 100× fewer partners, 100× the excess.`),
    q(md`Same two samples: which has the longer minority diffusion length?`,
      ['the lightly doped one', 'the heavily doped one', 'the same', 'it depends on the light'],
      ['Shorter τ and lower mobility.', 'Both τ and $D$ differ.', 'In low-level injection L does not depend on light.'],
      md`$L = \sqrt{D\tau}$: lighter doping gives a longer lifetime and a higher mobility (so higher $D$).`),
    q(md`p-type with $p_0 = 10^{17}$ and n-type with $n_0 = 10^{17}$, same $\alpha_r$ and light. Which minority lifetime is longer?`,
      ['neither: each sees $10^{17}$ partners', 'the electrons in the p-type, since electrons move faster', 'the holes in the n-type', 'neither has a lifetime'],
      ['Same partner density.', 'Same partner density.', 'Both have one.'],
      md`For direct recombination, $\tau = 1/(\alpha_r \times \text{majority})$, and both majorities are $10^{17}$.`),
    q(md`A sample has $N_d = 2\times10^{17}$ and $N_a = 10^{17}$. The majority density to use in the minority lifetime is…`,
      ['$10^{17}$ (net)', '$3\\times10^{17}$ (total)', '$2\\times10^{17}$ (donors)', '$n_i$ (compensated)'],
      ['Ions are not partners; only free electrons are.', 'Half the donors\' electrons fell into acceptors.', 'It is only partly compensated.'],
      md`Recombination needs free electrons: $n_0 = N_d - N_a = 10^{17}$. The **total** ($3\times10^{17}$) sets the mobility, not the partner count.`),
  ];

  // ============================================================ 5. building a junction
  S['5'] = [
    q(md`Why does a depletion region form when p and n touch?`,
      ['carriers diffuse across and leave fixed ions behind', 'the metal contacts pull carriers out', 'the gap narrows at the interface', 'recombination at the interface wipes out the carriers there'],
      ['It forms with no contacts at all.', 'The gap is unchanged.', 'Recombination does not create charge.'],
      md`Electrons leave the n side and holes the p side, uncovering + donors and − acceptors that cannot move.`),
    q(md`What stops the carriers from diffusing across forever?`,
      ['the ions\' field drives an opposite drift', 'the carriers run out on each side', 'recombination in the depletion region eats them up', 'the contacts block them'],
      ['There are plenty left; the field balances them.', 'Recombination is not the balancing mechanism.', 'Equilibrium is internal.'],
      md`The ions' field grows until drift exactly cancels diffusion for each carrier. That is equilibrium, and the Fermi level is flat.`),
    q(md`Both sides of a Si junction are doped 10× more heavily. $V_0$ changes by about…`,
      ['+0.12 V', '+0.06 V', '−0.12 V', '+1.2 V'],
      ['Both sides contribute 60 mV each.', 'More doping raises $V_0$.', 'It is logarithmic, not linear.'],
      md`$V_0 = (kT/q)\ln(N_aN_d/n_i^2)$: 100× more product is $0.0259\ln 100 = 0.12$ V. Each Fermi level moves 60 mV toward its band.`),
    q(md`In a $p^+n$ junction, the p side is made 10× more heavily doped still. What happens?`,
      ['$V_0$ rises a little; $W$ barely changes', '$W$ shrinks by √10 because the charge is denser', 'the peak field rises 10×', 'nothing at all'],
      ['$W$ is set by the light side.', 'The field is set by the light side too.', '$V_0$ gains about 60 mV.'],
      md`The light (n) side holds almost all of the depletion width and voltage. Heavier $p^+$ only nudges $V_0$ up by $kT\ln10$.`),
    q(md`A wire is connected across an unbiased p-n junction in the dark. Current flows…`,
      ['not at all', 'from p to n through the wire', 'from n to p through the wire', 'only until the depletion region collapses'],
      ['The metal contact potentials cancel $V_0$.', 'Same reason.', 'Equilibrium is stable.'],
      md`The contact potentials at the two metal contacts exactly cancel $V_0$ around the loop, so nothing flows. Otherwise a diode would be a free battery.`),
    q(md`Temperature rises. The contact potential of a Si junction…`,
      ['decreases', 'increases', 'is unchanged', 'first rises, then falls'],
      ['Higher $n_i$ pulls both Fermi levels toward midgap.', 'Temperature changes $n_i$ strongly.', 'It falls steadily.'],
      md`More intrinsic carriers bring each $E_F$ closer to midgap, so the Fermi levels started closer together: smaller $V_0$.`),
    q(md`Before contact, the n side's $E_F$ is higher. After contact…`,
      ['the n side\'s bands drop until the $E_F$ line up', 'the p side\'s $E_F$ rises to midgap', 'both $E_F$ settle at midgap', 'nothing moves until a bias is applied across the junction'],
      ['Far from the junction each side keeps its doping.', 'Each side keeps its own $E_F - E_i$.', 'Charge flows at once.'],
      md`Electrons pour from high $E_F$ to low until the Fermi levels match; the n side's bands drop by $qV_0$ relative to the p side's.`),
    q(md`The contact potential $qV_0$ equals…`,
      ['the Fermi-level difference before contact', 'the band gap', 'the sum of the two work functions, measured from vacuum', 'the applied voltage'],
      ['$V_0$ is less than $E_g/q$.', 'It is a difference, not a sum.', 'It exists with no bias.'],
      md`$qV_0 = E_{F,n} - E_{F,p}$ before contact $= kT\ln(N_aN_d/n_i^2)$.`),
    q(md`Can $V_0$ exceed $E_g/q$ in a nondegenerate junction?`,
      ['no: both Fermi levels stay inside the gap', 'yes, with heavy enough doping on both sides of the junction', 'yes, under reverse bias', 'only in GaAs'],
      ['Heavy enough means degenerate; then it can reach about $E_g$.', 'Bias changes the barrier, not $V_0$.', 'Same rule for every material.'],
      md`$qV_0$ is the distance between two levels that both sit between $E_v$ and $E_c$.`),
    q(md`At equilibrium, the hole **diffusion** current across the junction is…`,
      ['large, but canceled by an equal hole drift', 'zero, because the field stops every hole at the edge', 'equal to the electron diffusion current', 'the reverse saturation current'],
      ['Many holes still diffuse; the field sends just as many back.', 'They are separate balances.', 'That is a tiny drift current under reverse bias.'],
      md`Each carrier's drift and diffusion cancel separately. Both components are huge; bias upsets the balance a little and the difference is the diode current.`),
    q(md`Electrons on the n side face a barrier $qV_0$. A few still cross because…`,
      ['some have enough thermal energy', 'they tunnel through the band gap', 'the field helps them across', 'the barrier has holes in it'],
      ['Tunneling needs a very thin barrier.', 'The field pushes them back.', 'No.'],
      md`The fraction with energy above the barrier is $e^{-qV_0/kT}$. Forward bias lowers the barrier and lets exponentially more over.`),
  ];

  // ============================================================ 6. inside the depletion region
  S['6'] = [
    q(md`In an abrupt junction at equilibrium, where is the electric field strongest?`,
      ['at the metallurgical junction', 'at the edge on the light side', 'in the middle of the light side', 'it is uniform across the region'],
      ['It falls to zero at the edges.', 'It peaks where the charge changes sign.', 'It ramps linearly in each block.'],
      md`The field is the running sum of the charge: it builds through the + block, peaks where the charge changes sign, then unwinds through the − block.`),
    q(md`The n side is on the **right**. The built-in field points…`,
      ['left, from n to p', 'right, from p to n', 'up the band diagram', 'nowhere: each side is neutral'],
      ['Fields point from + to −.', 'Band diagrams are not spatial directions.', 'The depletion region is charged.'],
      md`+ ions on the n side (right), − ions on the p side (left): the field points from right to left.`),
    q(md`In a one-sided junction, the light-side doping is doubled. The peak field…`,
      ['rises by about √2', 'doubles, along with the doping', 'halves', 'is unchanged'],
      ['Field ∝ √(N V).', 'More doping raises it.', 'It depends on the light side.'],
      md`$W \propto 1/\sqrt{N}$ and peak field $= 2V/W \propto \sqrt{N}$ (ignoring the small change in $V_0$).`),
    q(md`A junction's charge density rises linearly through it (a graded junction). The potential looks like…`,
      ['a cubic S-curve', 'two parabolas', 'a straight line', 'a single parabola'],
      ['That is the abrupt junction.', 'That needs a constant field.', 'That needs a linear field.'],
      md`Linear charge → parabolic field → cubic potential. Each integration raises the power by one.`),
    q(md`In a $p^+n$ junction, which side's depletion layer holds more **charge per area**?`,
      ['neither: they are equal', 'the $p^+$ side', 'the n side', 'it depends on the voltage'],
      ['The field must vanish at both edges.', 'Taller but thinner.', 'Wider but lower.'],
      md`$N_ax_p = N_dx_n$: the charges are always equal and opposite.`),
    q(md`Which assumption lets you draw the charge as perfect rectangles?`,
      ['the depletion approximation', 'low-level injection', 'nondegenerate doping', 'long neutral regions on both sides'],
      ['That concerns injected carriers.', 'That concerns statistics.', 'That concerns diffusion profiles.'],
      md`It assumes no mobile carriers inside the depletion region, sharp edges, and neutrality outside.`),
    q(md`In a $p^+n$ junction, the depletion region lies mostly…`,
      ['in the lightly doped n side', 'in the heavily doped $p^+$ side', 'split evenly', 'outside the junction'],
      ['Heavy doping uncovers its charge in a thin sliver.', 'Equal charge, unequal widths.', 'No.'],
      md`$x_n/x_p = N_a/N_d$: the light side must go deep to uncover the same charge.`),
    q(md`The field rises **linearly** through each depletion block because…`,
      ['the charge in each block is uniform', 'the potential is linear', 'carriers drift through it at constant speed', 'the doping is graded'],
      ['The potential is parabolic.', 'No carriers are counted there.', 'Abrupt, not graded.'],
      md`Gauss: $d\mathscr{E}/dx = \rho/\epsilon$. Constant charge, constant slope.`),
    q(md`The area under the field-vs-position curve equals…`,
      ['the total voltage across the junction', 'the total uncovered charge on one side of it', 'the depletion width', 'the current'],
      ['Charge is the slope of the field.', 'That is the base of the triangle.', 'Equilibrium: no current.'],
      md`$V = \int\mathscr{E}\,dx$: the triangle's area is $\tfrac12\mathscr{E}_{\max}W = V_0 - V$.`),
    q(md`A $p^+n$ junction has $W = 0.4\ \mu\text{m}$ with $0.8$ V across it. The peak field is about…`,
      ['$4\\times10^4$ V/cm', '$2\\times10^4$ V/cm', '$8\\times10^4$ V/cm', '$2\\times10^5$ V/cm'],
      ['That is $V/W$: forgot the triangle.', 'That is $4V/W$.', 'Check the units: 0.4 µm is $4\\times10^{-5}$ cm.'],
      md`Triangle area $\tfrac12\mathscr{E}W = V$, so $\mathscr{E} = 2V/W = 1.6/(4\times10^{-5}) = 4\times10^4$ V/cm.`),
  ];

  // ============================================================ 7. applying a voltage
  S['7'] = [
    q(md`Under forward bias, why does the depletion region get narrower?`,
      ['less voltage across it needs less uncovered charge', 'the injected carriers flood in and fill it in completely', 'the doping rises under bias', 'the field reverses direction'],
      ['It still exists; the depletion approximation still holds.', 'Doping is fixed.', 'The field shrinks but keeps its direction.'],
      md`$W \propto \sqrt{V_0 - V}$: lowering the voltage across it means fewer ions need to be uncovered.`),
    q(md`Where does almost all of an applied diode voltage drop?`,
      ['across the depletion region', 'across the long neutral regions', 'at the metal contacts', 'evenly along the device'],
      ['They are full of carriers: low resistance.', 'Ideal contacts drop nothing.', 'The depletion region is the bottleneck.'],
      md`The depletion region has almost no carriers, so it is by far the most resistive piece.`),
    q(md`A forward-biased diode's voltage rises by 60 mV. The current…`,
      ['rises about 10×', 'rises about 2.7×', 'rises by 60%', 'doubles'],
      ['That is one $kT$ (26 mV).', 'It is exponential.', 'That is 18 mV.'],
      md`$e^{0.06/0.0259} \approx 10$: 60 mV per decade.`),
    q(md`Under reverse bias, the minority concentration at each depletion edge is…`,
      ['pushed nearly to zero', 'multiplied by $e^{qV_R/kT}$', 'unchanged from equilibrium', 'raised to the majority level'],
      ['That would be forward-bias injection.', 'The barrier changed.', 'No.'],
      md`$e^{-qV_R/kT}$ is tiny: the edge is a sink, and minority carriers nearby are extracted.`),
    q(md`Inside the depletion region of a forward-biased diode, $F_n - F_p$ equals…`,
      ['$qV$', '$qV_0$', '$q(V_0 - V)$', 'zero'],
      ['That is the equilibrium step of the bands.', 'That is the barrier height.', 'That would be equilibrium.'],
      md`The quasi-Fermi levels split by exactly the applied voltage: that split *is* $V$.`),
    q(md`Can you forward bias the junction itself beyond $V_0$?`,
      ['no: extra voltage drops elsewhere', 'yes: the barrier simply flips and reverses', 'yes, and the current then falls', 'only in a narrow-base diode'],
      ['The barrier flattens, then series resistance takes over.', 'Current keeps rising.', 'Same limit.'],
      md`As $V$ approaches $V_0$ the barrier flattens and high-level injection and the neutral-region resistance take the rest of the voltage.`),
    q(md`Forward bias $V$ multiplies the minority density at each depletion edge by…`,
      ['$e^{qV/kT}$', '$qV/kT$', '$e^{-qV/kT}$', '$\\sqrt{V}$'],
      ['It is exponential, not linear.', 'That is reverse bias.', 'That is how $W$ scales.'],
      md`The law of the junction: $p_n(\text{edge}) = p_{n0}e^{qV/kT}$. At 0.6 V that is a factor of about $10^{10}$.`),
    q(md`Why does the injected current rise **exponentially** with forward voltage?`,
      ['the thermal energy tail is exponential', 'the field accelerates the carriers', 'the depletion region shrinks linearly with V', 'more donors ionize'],
      ['The barrier field opposes them.', '$W$ goes as a square root.', 'They are already ionized.'],
      md`Lowering the barrier by $qV$ admits the carriers in the Boltzmann tail, whose count grows as $e^{qV/kT}$.`),
    q(md`Under bias, which current component barely changes?`,
      ['minority carriers drifting across', 'majority carriers diffusing over the barrier', 'both change equally', 'neither changes'],
      ['That is the one bias controls.', 'Only one depends on the barrier.', 'Then no diode current would flow.'],
      md`The drift (generation) current is limited by how many minority carriers wander to the edge, not by the barrier height. Diffusion over the barrier is what bias controls.`),
    q(md`On a forward-biased band diagram, compared with equilibrium, the n side's bands are…`,
      ['raised by $qV$ relative to the p side', 'lowered by $qV$ relative to the p side', 'unchanged', 'raised by $qV_0$'],
      ['That raises the step: reverse bias.', 'The step shrinks from $qV_0$ to $q(V_0 - V)$.', 'That would remove the barrier entirely.'],
      md`In equilibrium the n side sits $qV_0$ lower. Forward bias shrinks the step to $q(V_0 - V)$.`),
    q(md`A diode is reverse biased at 5 V. In the depletion region, $F_n - F_p$ is…`,
      ['−5 eV: $F_n$ below $F_p$', '+5 eV: $F_n$ sits above $F_p$', 'zero', '$E_g$'],
      ['That is forward bias.', 'That is equilibrium.', 'The split is set by the bias.'],
      md`The split equals $qV$ with $V = -5$ V: $np \ll n_i^2$ there, so generation beats recombination.`),
  ];

  // ============================================================ 8. where the diode current comes from
  S['8'] = [
    q(md`Why is the reverse current flat, even as the reverse voltage grows?`,
      ['it is limited by the supply of minority carriers', 'the field saturates at high reverse bias and stops growing', 'the depletion region stops widening', 'recombination cancels any extra current'],
      ['The field keeps growing.', 'It keeps widening as √V.', 'Nothing is canceling it.'],
      md`Every minority carrier that reaches the edge is already swept across; more field cannot sweep more than arrive.`),
    q(md`A Si diode heats up. Its reverse saturation current…`,
      ['rises steeply', 'falls', 'stays the same', 'rises linearly with temperature'],
      ['More heat makes more pairs.', 'It tracks $n_i^2$.', 'It is exponential through $n_i^2$.'],
      md`$I_0 \propto n_i^2 \propto e^{-E_g/kT}$: a few degrees makes a large difference.`),
    q(md`A GaAs and a Si diode have the same doping. At the same forward current, the GaAs diode needs…`,
      ['more forward voltage', 'less forward voltage', 'the same voltage', 'reverse bias'],
      ['Its $I_0$ is far smaller.', 'Doping is not the only factor: the gap is.', 'No.'],
      md`A wider gap means a much smaller $n_i^2$ and $I_0$, so the exponential must climb higher: GaAs turns on near 1 V, Si near 0.7 V.`),
    q(md`In a $p^+n$ diode, which carriers carry the current across the junction?`,
      ['holes injected into the n side', 'electrons injected into the $p^+$ side', 'both equally', 'majority electrons drifting'],
      ['The $p^+$ side has almost no minority electrons.', 'Only with equal doping.', 'That is far from the junction.'],
      md`Injection is proportional to the minority density $n_i^2/N$, which is largest on the light side.`),
    q(md`Far from the junction in the n region of a forward-biased diode, the current is carried by…`,
      ['majority electrons drifting', 'holes diffusing', 'nothing: the current has died out', 'electrons diffusing'],
      ['The injected holes have recombined.', 'The total current is constant everywhere.', 'There is no gradient there.'],
      md`Each recombining hole needs an electron, supplied by majority drift from the contact: the total current stays constant.`),
    q(md`A diode's lifetime is doubled at the same forward current. The stored minority charge…`,
      ['doubles', 'halves', 'stays the same', 'rises by √2'],
      ['$Q = I\\tau$.', 'The current is fixed.', 'It is linear in τ.'],
      md`Each carrier lives twice as long, so twice as many are stored at once for the same replacement rate.`),
    q(md`A narrow-base diode, compared with a long one at the same voltage, has…`,
      ['more current, less stored charge', 'less current, more stored charge', 'the same current, less stored charge', 'more current and more stored charge'],
      ['The line is steeper than the exponential.', 'Current depends on the slope.', 'The triangle holds less charge.'],
      md`Slope $\Delta/\ell$ beats $\Delta/L$, and the triangle $\tfrac12\Delta\ell$ is smaller than $\Delta L$.`),
    q(md`At very low forward current, a real Si diode's current rises more slowly than $e^{qV/kT}$. Why?`,
      ['recombination in the depletion region dominates', 'series resistance in the neutral regions and contacts', 'high-level injection', 'avalanche multiplication'],
      ['That matters at high current.', 'That is high current.', 'That is reverse bias.'],
      md`Recombination in the depletion region grows like $e^{qV/2kT}$ and wins at low current.`),
    q(md`Right next to the junction on the n side of a forward-biased $p^+n$ diode, the current is mostly…`,
      ['holes diffusing', 'electrons drifting', 'holes drifting', 'electrons diffusing'],
      ['The handoff to electrons happens over a few $L_p$.', 'The neutral region has almost no field.', 'Electron injection into $p^+$ is tiny.'],
      md`The injected holes have their steepest slope right at the edge; over a few $L_p$ they recombine and the majority electrons take over.`),
    q(md`$I_0$ of a $p^+n$ diode depends mostly on…`,
      ['the doping of the n side', 'the doping of the $p^+$ side', 'both equally', 'the applied voltage'],
      ['The $p^+$ side injects almost nothing.', 'The light side dominates.', '$I_0$ is a constant.'],
      md`$I_0 \approx qA\dfrac{D_p}{L_p}\dfrac{n_i^2}{N_d}$: the light side's minority density sets it.`),
    q(md`Doubling a diode's area doubles…`,
      ['$I_0$ and the current at a given voltage', 'the turn-on voltage, since there is more to fill', 'the contact potential', 'nothing'],
      ['A bigger diode needs less voltage for the same current.', '$V_0$ is set by doping.', 'Current scales with area.'],
      md`Every current density is per area, so $I = AJ$.`),
  ];

  // ============================================================ 9. breakdown
  S['9'] = [
    q(md`A breakdown diode's breakdown voltage **falls** as it heats up. The mechanism is most likely…`,
      ['Zener tunneling', 'avalanche', 'punch-through', 'thermal runaway'],
      ['Avalanche voltage rises with temperature.', 'Not a temperature trend.', 'Not a breakdown mechanism here.'],
      md`The gap shrinks with temperature, making tunneling easier: Zener has a negative temperature coefficient. Avalanche is positive (more phonon scattering).`),
    q(md`Why does avalanche breakdown voltage **rise** with temperature?`,
      ['more scattering: less energy between collisions', 'the gap widens with temperature', 'more thermal carriers screen the field in the depletion region', 'the depletion region narrows'],
      ['The gap shrinks with temperature.', 'Not the mechanism.', 'Temperature barely changes W.'],
      md`Hot lattices scatter carriers more often, so they need a bigger field to reach ionization energy.`),
    q(md`A junction's light-side doping is raised. Its breakdown voltage…`,
      ['falls', 'rises', 'is unchanged', 'disappears'],
      ['A thinner region reaches the critical field sooner.', 'It depends strongly on doping.', 'Breakdown always exists.'],
      md`Heavier doping thins $W$ and raises the field at a given voltage.`),
    q(md`How do you check whether a $p^+n$ diode breaks down by punch-through?`,
      ['compare $W$ at avalanche with the n-region length', 'check whether $V_{br}$ exceeds $V_0$', 'check the sign of the temperature coefficient of the breakdown', 'compare the doping on the two sides'],
      ['$V_{br}$ always exceeds $V_0$.', 'That separates Zener from avalanche.', 'One-sided either way.'],
      md`If the depletion region would reach the end of the region before the avalanche field, it punches through first.`),
    q(md`GaAs and Si junctions with the same doping: which breaks down at the higher reverse voltage?`,
      ['GaAs', 'Si', 'the same', 'GaAs only when cold'],
      ['A wider gap needs more energy per new pair.', 'Doping is not the only factor.', 'True at room temperature too.'],
      md`A wider gap needs a higher critical field for impact ionization.`),
    q(md`In avalanche breakdown, one carrier crossing the depletion region…`,
      ['knocks loose pairs that knock loose more', 'tunnels straight from band to band through the barrier', 'is trapped at the junction', 'recombines and gives off light'],
      ['That is Zener.', 'No.', 'No.'],
      md`Impact ionization: each hot carrier makes a new pair, and those make more. The current runs away at the critical field.`),
    q(md`Zener breakdown needs…`,
      ['heavy doping on both sides', 'a long, lightly doped region', 'high temperature', 'forward bias'],
      ['That gives avalanche at high voltage.', 'Not required.', 'It is a reverse-bias effect.'],
      md`Tunneling needs a barrier only a few nm thick: a very thin depletion region from heavy doping on both sides.`),
    q(md`A diode breaks down at 3 V. The mechanism is most likely…`,
      ['Zener tunneling', 'avalanche', 'punch-through', 'not breakdown at all'],
      ['Avalanche usually needs more than about 6 V.', 'Possible, but a 3 V diode is a Zener.', 'It is.'],
      md`Low breakdown voltage means heavy doping and a thin barrier: tunneling. Above about 6 V, avalanche takes over.`),
    q(md`A diode breaks down at 200 V. Its light-side doping is…`,
      ['light', 'heavy', 'degenerate', 'irrelevant'],
      ['Heavy doping breaks down early.', 'That gives Zener at a few volts.', 'It sets the breakdown voltage.'],
      md`$V_{br} \propto 1/N$ for avalanche: a high breakdown voltage needs a lightly doped, wide region.`),
    q(md`Is breakdown itself destructive?`,
      ['not unless the current makes too much heat', 'always', 'never, at any current', 'only in Zener diodes, whose thin barrier is fragile'],
      ['Zener diodes run in breakdown all day.', 'Too much power burns it out.', 'Both mechanisms are reversible.'],
      md`Breakdown is reversible. The damage comes from $I\times V_{br}$ heat if the circuit does not limit the current.`),
  ];

  // ============================================================ 10. capacitance and switching
  S['10'] = [
    q(md`A diode's reverse voltage is raised so $V_0 + V_R$ doubles. Its junction capacitance…`,
      ['falls by √2', 'halves', 'doubles', 'is unchanged'],
      ['$W \\propto \\sqrt{V}$, $C \\propto 1/W$.', 'Reverse bias widens W, lowering C.', 'It depends on W.'],
      md`$C_j \propto 1/\sqrt{V_0 + V_R}$.`),
    q(md`On a plot of $1/C_j^2$ vs reverse voltage, one diode's line is steeper. That diode has…`,
      ['lighter doping on its light side', 'heavier doping on its light side', 'a larger contact potential', 'a larger area'],
      ['The slope is ∝ 1/N.', 'That sets the intercept.', 'A larger area flattens it.'],
      md`$1/C_j^2 = 2(V_0 + V_R)/(q\epsilon NA^2)$: slope ∝ 1/N. The intercept is at $-V_0$.`),
    q(md`Which capacitance dominates under forward bias?`,
      ['storage (diffusion) capacitance', 'junction (depletion) capacitance', 'they are equal', 'neither: forward bias has none'],
      ['Stored charge grows exponentially with V.', 'Different physics, different sizes.', 'Stored charge changes with V.'],
      md`$C_s \propto I\tau$ is nanofarads at milliamps, far above the picofarad $C_j$.`),
    q(md`A diode carrying forward current is switched to reverse. During the storage delay…`,
      ['big reverse current, junction still forward biased', 'no current flows', 'the junction is reverse biased and the current is tiny', 'the current falls exponentially from the start'],
      ['The stored charge drives a reverse current.', 'The stored holes keep the edge excess positive.', 'That happens after the delay.'],
      md`Until the stored minority charge is removed, the edge excess stays positive, so the junction is still forward biased and a big reverse current flows.`),
    q(md`Which change would **not** speed up a diode's turn-off?`,
      ['a longer minority lifetime', 'gold doping', 'a narrow base', 'switching to a Schottky diode instead'],
      ['Gold creates recombination centers, shortening τ.', 'Less stored charge.', 'No minority storage at all.'],
      md`More lifetime means more stored charge to remove: slower.`),
    q(md`A $p^+n^+$ diode vs a $p^+n$ diode: which has more reverse-bias capacitance?`,
      ['the $p^+n^+$', 'the $p^+n$', 'the same', 'neither has any'],
      ['Heavier doping on both sides gives the thinnest W.', 'Doping changes W.', 'Every junction has $C_j$.'],
      md`$C_j = \epsilon A/W$, and $p^+n^+$ has the thinnest depletion region.`),
    q(md`A varactor is…`,
      ['a reverse-biased diode used as a tunable capacitor', 'a forward-biased diode used as a voltage-controlled resistor', 'a breakdown diode used as a reference', 'a photodiode used as a capacitor'],
      ['Forward bias is not used.', 'That is a Zener diode.', 'Light is not involved.'],
      md`Reverse bias sets $W$, and so $C_j$: tune the voltage, tune the capacitance.`),
    q(md`Junction capacitance comes from…`,
      ['the depletion edges moving as $V$ changes', 'stored minority carriers', 'the metal contacts', 'extra charge stored in the neutral regions'],
      ['That is storage capacitance.', 'Ideal contacts store nothing.', 'They stay neutral.'],
      md`Change the voltage and the edges move, uncovering or covering a sliver of ions on each side: a parallel-plate capacitor with gap $W$.`),
    q(md`Storage capacitance is large when…`,
      ['the forward current or lifetime is large', 'the reverse bias is large and the region is wide', 'the doping is heavy', 'the diode is cold'],
      ['Reverse bias stores nothing.', 'Not directly.', 'Temperature enters only through $I$.'],
      md`$C_s = dQ/dV = \tau\,dI/dV = \tau I/(kT/q)$.`),
    q(md`After the storage delay, the reverse current…`,
      ['decays to $I_0$ as the depletion region widens', 'jumps back to the forward current as the charge returns', 'stays large forever', 'reverses direction again'],
      ['No.', 'The stored charge is gone.', 'No.'],
      md`With the stored charge gone, the junction reverse biases and only the small junction-capacitance charging current remains, decaying to $I_0$.`),
  ];

  // ============================================================ 11. metal–semiconductor
  S['11'] = [
    q(md`A metal with $\phi_m > \phi_s$ touches n-type Si. Electrons flow…`,
      ['from the semiconductor into the metal', 'from the metal into the semiconductor', 'in neither direction', 'back and forth until the metal heats'],
      ['The metal Fermi level is deeper.', 'They balance at once.', 'No.'],
      md`Electrons fall toward the deeper Fermi level, leaving a depletion region of + donors in the semiconductor: rectifying.`),
    q(md`Which contact is **rectifying**?`,
      ['p-type with $\\phi_m < \\phi_s$', 'p-type with $\\phi_m > \\phi_s$', 'n-type with $\\phi_m < \\phi_s$', 'n-type heavily doped at the surface'],
      ['Holes accumulate: ohmic.', 'Electrons accumulate: ohmic.', 'Tunneling makes it ohmic.'],
      md`For p-type, $\phi_m < \phi_s$ pushes electrons **into** the semiconductor, filling holes near the surface: a depletion region and a barrier for holes.`),
    q(md`The doping of an n-type wafer is raised under the same metal. The barrier $\phi_B$ seen from the metal…`,
      ['is unchanged', 'rises with the doping', 'falls', 'vanishes'],
      ['$\\phi_B = \\phi_m - \\chi$ has no doping in it.', 'Same reason.', 'It is pinned by $\\phi_m$ and $\\chi$.'],
      md`Doping moves $\phi_s$ (and so $V_0$) but not $\phi_m - \chi$. What doping does change is the barrier **width**: thinner, until carriers tunnel through.`),
    q(md`Why is a heavily doped surface the standard way to make an ohmic contact?`,
      ['the barrier gets thin enough to tunnel through', 'heavy doping removes the barrier height completely', 'it lowers the metal work function', 'it raises the electron affinity'],
      ['The height stays; the width shrinks.', 'The metal is unchanged.', '$\\chi$ is a material property.'],
      md`$W \propto 1/\sqrt{N}$: at very high doping the barrier is a few nm thick, and carriers tunnel straight through.`),
    q(md`Why does a Schottky diode switch faster than a p-n diode?`,
      ['it stores no minority charge', 'its barrier is higher', 'it has more capacitance', 'its carriers move faster through the metal'],
      ['A lower barrier, if anything.', 'Not the reason.', 'Same carriers; no storage is the key.'],
      md`Current is majority carriers over the barrier; nothing has to be removed when it turns off.`),
    q(md`Compared with a Si p-n diode, a Schottky diode turns on at…`,
      ['a lower forward voltage', 'a higher forward voltage', 'the same voltage', 'only under reverse bias'],
      ['Its saturation current is much larger.', 'Different physics.', 'No.'],
      md`$I_0 \propto e^{-\phi_B/kT}$ is large for a barrier well below the gap, so less voltage gives the same current.`),
    q(md`Forward bias for a metal on n-type Si means…`,
      ['the metal positive', 'the semiconductor positive', 'no bias at all', 'both at the same potential'],
      ['That raises the barrier: reverse.', 'Then nothing changes.', 'Same.'],
      md`Making the metal positive lowers the semiconductor-side barrier $q(V_0 - V)$, so electrons pour over into the metal.`),
    q(md`Under forward bias in a Schottky diode, which barrier changes?`,
      ['the semiconductor-side barrier $qV_0$', 'the metal-side barrier $\\phi_B$ at the interface', 'both by the same amount', 'neither'],
      ['$\\phi_B$ is pinned at the interface.', 'Only the band bending changes.', 'The current would not change then.'],
      md`Bias moves the bands in the semiconductor, not the interface: $q(V_0 - V)$ changes, $\phi_B$ stays.`),
    q(md`A metal with $\phi_m < \phi_s$ on n-type Si gives…`,
      ['an ohmic contact', 'a rectifying contact', 'a depletion region in the metal', 'a barrier for holes only'],
      ['Electrons flow in and accumulate: no barrier.', 'Metals do not deplete.', 'Holes are the minority here.'],
      md`Electrons flow into the semiconductor and accumulate at the surface: no depletion, no barrier for the majority electrons.`),
    q(md`Electrons flow at a metal–semiconductor contact until…`,
      ['the two Fermi levels line up', 'the work functions become equal', 'the conduction bands line up', 'the semiconductor becomes intrinsic'],
      ['Work functions are material properties; they do not change.', 'The bands bend; they do not align.', 'Only the surface region changes.'],
      md`Equilibrium means one flat Fermi level through both materials; the bands bend to make that happen.`),
  ];

  // ============================================================ 12. junctions and light
  S['12'] = [
    q(md`Light at 1.55 µm (0.8 eV) shines on silicon ($E_g = 1.12$ eV). It is…`,
      ['mostly transmitted', 'strongly absorbed', 'absorbed only by holes', 'reflected completely'],
      ['The photon energy is below the gap.', 'There is no such process.', 'Only partly reflected.'],
      md`Below the gap there are no states to absorb into. That is why fiber-optic detectors use InGaAs, not Si.`),
    q(md`Inside an illuminated diode, the photocurrent flows…`,
      ['in the reverse direction, n to p', 'in the forward direction, p to n', 'only through the neutral regions', 'in both directions equally'],
      ['The field sweeps electrons to n and holes to p.', 'It is collected by the field.', 'No.'],
      md`Electrons go to the n side and holes to the p side: conventional current from n to p inside, opposite to forward current.`),
    q(md`Why reverse-bias a photodiode for communications?`,
      ['wider depletion: more collected, faster response', 'reverse bias multiplies the photocurrent by the voltage', 'it generates power', 'it removes all noise'],
      ['Current is limited by the photons absorbed (barring avalanche).', 'That is a solar cell.', 'Noise never reaches zero.'],
      md`More light is absorbed inside the field region, where carriers drift (fast) instead of diffusing (slow), and the current is independent of voltage.`),
    q(md`A solar cell is lit 10× more brightly. Its open-circuit voltage…`,
      ['rises by about 60 mV', 'rises 10×', 'rises by √10', 'stays the same: it is set by the gap'],
      ['$V_{oc}$ is logarithmic in light.', 'Not a square root.', 'It does change.'],
      md`$V_{oc} \approx (kT/q)\ln(I_{sc}/I_0)$: ten times the current, one decade, 60 mV.`),
    q(md`A solar cell heats up. Its open-circuit voltage…`,
      ['falls', 'rises', 'stays the same', 'drops to zero'],
      ['$I_0$ soars with temperature.', 'Temperature matters through $I_0$.', 'It falls, but stays positive.'],
      md`A much larger $I_0$ means less forward voltage is needed to cancel the photocurrent.`),
    q(md`Two identical solar cells are connected in parallel. Compared with one cell…`,
      ['$I_{sc}$ doubles; $V_{oc}$ is unchanged', '$V_{oc}$ doubles; $I_{sc}$ is unchanged', 'both double', 'neither changes'],
      ['That is series.', 'Only power doubles.', 'Currents add in parallel.'],
      md`Parallel: same voltage, currents add. Series: same current, voltages add.`),
    q(md`The fill factor of a solar cell compares…`,
      ['the maximum power with $V_{oc}I_{sc}$', 'the photocurrent with the dark current', 'absorbed power with incident power', '$V_{oc}$ with the band gap'],
      ['That is not a defined ratio.', 'That is a quantum efficiency.', 'Not the definition.'],
      md`$FF = P_{\max}/(V_{oc}I_{sc})$: how "square" the I–V curve is.`),
    q(md`Why can't a silicon LED compete with GaAs?`,
      ['Si is indirect: recombination makes heat', 'Si has too small a gap', 'Si cannot be doped p-type', 'Si absorbs all the light it makes before it escapes'],
      ['Its gap is fine for near-IR light.', 'It dopes easily.', 'Not the main reason.'],
      md`Radiative recombination in an indirect gap needs a phonon, so it is rare; traps win and the energy becomes heat.`),
    q(md`An LED's alloy is changed to widen its gap. The emitted light…`,
      ['shifts to shorter wavelength', 'shifts to longer wavelength', 'stays the same color, brighter', 'becomes coherent'],
      ['Photon energy ≈ gap.', 'Color follows the gap.', 'Coherence needs a laser.'],
      md`$\lambda = 1.24\,\mu\text{m}/E_g$: a bigger gap means bluer light.`),
    q(md`Why is an LED's quantum efficiency below 1?`,
      ['some recombination is dark; some photons stay trapped', 'electrons lose some of their charge as they recombine in the gap', 'every photon needs two electrons', 'the gap absorbs photons first'],
      ['Charge is conserved.', 'One electron makes at most one photon.', 'Photons near the gap are only weakly reabsorbed.'],
      md`Nonradiative recombination (traps, surfaces) and internal reflection both lose photons.`),
    q(md`What must hold for a semiconductor laser to have gain?`,
      ['$F_n - F_p > E_g$', '$F_n - F_p < E_g$', '$F_n = F_p$', '$E_F$ at midgap'],
      ['That gives absorption.', 'That is equilibrium.', 'That is intrinsic material.'],
      md`Population inversion: states at the band edges must be more full above than below.`),
    q(md`Below threshold current, a laser diode behaves like…`,
      ['an LED (mostly spontaneous emission)', 'a photodiode', 'an open circuit', 'a weaker laser with the same coherent beam'],
      ['It is forward biased and emitting.', 'Current flows.', 'Stimulated emission has not taken over yet.'],
      md`Until gain beats the cavity losses, the light is mostly spontaneous: broad and incoherent.`),
    q(md`Why is laser light coherent?`,
      ['stimulated emission copies the triggering photon', 'the cavity mirrors filter out all but one color and phase', 'the gap is very narrow', 'the laser is reverse biased'],
      ['Filtering helps the spectrum, but coherence comes from copying.', 'The gap is normal.', 'Lasers are forward biased.'],
      md`Each stimulated photon has the same frequency, phase and direction as the one that triggered it.`),
    q(md`To make a photodiode collect more photocurrent, you would…`,
      ['lower the doping so W and L grow', 'raise the doping to sharpen the junction', 'forward bias it', 'make the junction narrower'],
      ['That shrinks W and L.', 'That works against the photocurrent.', 'The opposite.'],
      md`$I_{op} = qAg_{op}(L_n + L_p + W)$: lighter doping widens W and lengthens the diffusion lengths.`),
  ];

  // ---------------------------------------------------- splice each set in at the end of its section of "Exam 2 on one page"
  const NEXT = { '1': '2', '2': '3', '3': '4', '4': '4b', '4b': '5', '5': '6', '6': '7', '7': '8', '8': '9', '9': '10', '10': '11', '11': '12', '12': '13' };
  const lesson = COURSE.units.flatMap((u) => u.lessons).find((l) => l.id === 'e2-one');
  if (lesson) {
    for (const [sec, items] of Object.entries(S)) {
      const re = new RegExp(`(^|\\n)\\s*## ${NEXT[sec]}\\. `);
      const at = lesson.steps.findIndex((s) => s.t === 'read' && re.test(s.md || ''));
      if (at < 0) continue;
      lesson.steps.splice(at, 0, R(md`### Intuition check: ${items.length} questions

Say the reason out loud before you tap. Every option explains itself, right or wrong.`), ...items);
    }
  }

  const total = Object.values(S).reduce((n, a) => n + a.length, 0);
  C.unit({
    id: 'e2-gym', exam: 'e2', tools: true, num: 'Exam 2', title: 'Intuition drill',
    lessons: [{ id: 'gym-all', title: `Intuition drill: all ${total} checks, shuffled`, kind: 'quiz', noBank: true,
      steps: [R(md`Every intuition check from **Exam 2 on one page**, shuffled across all topics, with no repeats until the pool runs out. Aim for under 30 seconds each, with a reason you could say out loud.`), G('concept', { tags: ['gym'], need: 40 })] }],
  });
})();
